def compute(vars):
    fleet_berths = vars["v1"]
    expected_additions = vars["v2"]

    if fleet_berths == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    increase_percentage = expected_additions / fleet_berths * 100
    return {
        "value": increase_percentage,
        "trace": {
            "expected_additions": expected_additions,
            "fleet_berths": fleet_berths,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"},
        },
    }
